{
  "case_id": "lit-009",
  "title": "Named balance-system review",
  "software_contract": "review(request) validates a dense square system then reports current residual. solve mode uses partial-pivoted elimination (largest absolute pivot, first index tie) and back substitution, raises ValueError on exact zero pivot or detected numerical overflow, and returns named float solution, deltas and proposed residual. inspect does not solve and need not reject a singular matrix. Residual vector is Ax-b. scaled_backward_error is its infinity norm divided by machine epsilon*(||A||inf*||x||inf+||b||inf)*n. Zero/zero is 0; nonzero/zero is null. within_requested_limit compares the proposed scaled diagnostic to caller residual_limit; not a quantum-semantic acceptance criterion. Empty system yields empty solution and zero residual. No mutation. This is a small serial Python program, not a compliant HPL performance run.",
  "input_domain": "Exactly variables (distinct names), matrix (n rows of n finite real numbers), rhs/current (n finite numbers), residual_limit (finite nonnegative number), mode inspect|solve. Bool excluded from numbers. Computation uses Python binary64; values outside that range rejected; detected nonfinite results raise ValueError. No condition-number guarantee or bitwise match to a particular HPL installation.",
  "execution_assumptions": [
    "Classical inputs and outputs; no workload, quantum hardware, encoding-cost or advantage evidence supplied."
  ]
}

FILE program.py
1: """Review a named balance system, optionally compute a replacement vector."""
2: import json
3: import sys
4: from common import fields, finite, names, vector
5: from kernel import residual, solve
6: 
7: 
8: def review(request):
9:     fields(request, ("variables", "matrix", "rhs", "current", "mode", "residual_limit"))
10:     variables = names(request["variables"])
11:     n = len(variables)
12:     if not isinstance(request["matrix"], list) or len(request["matrix"]) != n:
13:         raise ValueError("square matrix required")
14:     matrix = [vector(row, n) for row in request["matrix"]]
15:     rhs, current = vector(request["rhs"], n), vector(request["current"], n)
16:     limit = finite(request["residual_limit"])
17:     if limit < 0 or request["mode"] not in ("inspect", "solve"):
18:         raise ValueError("invalid limit or mode")
19:     before = residual(matrix, rhs, current)
20:     report = {"current_residual": before, "proposal": None, "proposed_residual": None,
21:               "within_requested_limit": None, "deltas": None}
22:     if request["mode"] == "solve":
23:         x = solve(matrix, rhs)
24:         after = residual(matrix, rhs, x)
25:         report.update(proposal=dict(zip(variables, x)), proposed_residual=after,
26:                       within_requested_limit=after["scaled_backward_error"] is not None and after["scaled_backward_error"] <= limit,
27:                       deltas=dict(zip(variables, [finite(a - b) for a, b in zip(x, current)])))
28:     return report
29: 
30: 
31: if __name__ == "__main__":
32:     print(json.dumps(review(json.load(sys.stdin)), indent=2))

FILE kernel.py
1: """Dense elimination with partial pivoting and an HPL-style residual diagnostic.
2: 
3: New small Python implementation of the documented problem, not an HPL port/rating.
4: """
5: import math
6: import sys
7: 
8: 
9: def solve(matrix, rhs):
10:     n = len(rhs)
11:     rows = [list(row) + [b] for row, b in zip(matrix, rhs)]
12:     for col in range(n):
13:         pivot = max(range(col, n), key=lambda i: abs(rows[i][col]))
14:         if rows[pivot][col] == 0:
15:             raise ValueError("singular system")
16:         rows[col], rows[pivot] = rows[pivot], rows[col]
17:         for i in range(col + 1, n):
18:             factor = rows[i][col] / rows[col][col]
19:             for j in range(col, n + 1):
20:                 rows[i][j] -= factor * rows[col][j]
21:     x = [0.0] * n
22:     for i in range(n - 1, -1, -1):
23:         x[i] = (rows[i][n] - sum(rows[i][j] * x[j] for j in range(i + 1, n))) / rows[i][i]
24:     if any(not math.isfinite(v) for v in x):
25:         raise ValueError("numerical overflow")
26:     return x
27: 
28: 
29: def residual(matrix, rhs, x):
30:     errors = [sum(a * v for a, v in zip(row, x)) - b for row, b in zip(matrix, rhs)]
31:     norm = max(map(abs, errors), default=0.0)
32:     a_norm = max((sum(map(abs, row)) for row in matrix), default=0.0)
33:     denominator = sys.float_info.epsilon * (a_norm * max(map(abs, x), default=0.0)
34:                    + max(map(abs, rhs), default=0.0)) * len(rhs)
35:     if any(not math.isfinite(v) for v in errors + [norm, denominator]):
36:         raise ValueError("numerical overflow")
37:     scaled = norm / denominator if denominator else (0.0 if norm == 0 else None)
38:     return {"vector": errors, "infinity_norm": norm, "scaled_backward_error": scaled}

