              ],
              "properties": {
                "negative_reason": {
                  "type": "string",
                  "minLength": 1
                }
              },
              "anyOf": [
                {
                  "properties": {
                    "structural_eligibility": {
                      "const": false
                    }
                  }
                },
                {
                  "properties": {
                    "practical_suitability": {
                      "const": false
                    }
                  }
                },
